#include <vector>
#include <queue>

class Solution {
public:
    int countRecoveryPathways(int n, std::vector<std::vector<int>>& edges) {
        long long MOD = 1000000007;
        std::vector<std::vector<int>> adj(n);
        std::vector<int> indegree(n, 0);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            indegree[e[1]]++;
        }

        std::vector<long long> dp(n, 0);
        dp[0] = 1;

        std::queue<int> qu;
        for (int i = 0; i < n; ++i) {
            if (indegree[i] == 0) qu.push(i);
        }

        while (!qu.empty()) {
            int u = qu.front();
            qu.pop();

            for (int v : adj[u]) {
                dp[v] = (dp[v] + dp[u]) % MOD;
                if (--indegree[v] == 0) qu.push(v);
            }
        }

        return dp[n - 1];
    }
};

import java.util.*;

class Solution {
    public int countRecoveryPathways(int n, int[][] edges) {
        long mod = 1000000007L;
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] indegree = new int[n];
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            indegree[e[1]]++;
        }

        long[] dp = new long[n];
        dp[0] = 1;

        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) queue.add(i);
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj.get(u)) {
                dp[v] = (dp[v] + dp[u]) % mod;
                if (--indegree[v] == 0) queue.add(v);
            }
        }

        return (int) dp[n - 1];
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number}
 */
var countRecoveryPathways = function(n, edges) {
    const MOD = 1000000007n;
    const adj = Array.from({ length: n }, () => []);
    const indegree = new Int32Array(n);
    for (const [u, v] of edges) {
        adj[u].push(v);
        indegree[v]++;
    }

    const dp = new BigInt64Array(n);
    dp[0] = 1n;

    const queue = [];
    for (let i = 0; i < n; i++) {
        if (indegree[i] === 0) queue.push(i);
    }

    let head = 0;
    while (head < queue.length) {
        const u = queue[head++];
        for (const v of adj[u]) {
            dp[v] = (dp[v] + dp[u]) % MOD;
            indegree[v]--;
            if (indegree[v] === 0) queue.push(v);
        }
    }

    return Number(dp[n - 1]);
};
